// Direct PDF layout drawing engine using jsPDF coordinates in mm.
// Self-contained Unicode font support for DM Sans to render Vietnamese characters correctly.

(function() {
    const DMSansRegularB64 = "";
    const DMSansBoldB64 = "";

    // Export function to global scope
    window.exportDesignPdf = function(designData) {
        return new Promise(async (resolve, reject) => {
            try {
                const { jsPDF } = window.jspdf ? window.jspdf : window;
                const pdf = new jsPDF({
                    orientation: 'portrait',
                    unit: 'mm',
                    format: 'a4'
                });

                // Register Unicode fonts
                pdf.addFileToVFS('DMSans-Regular.ttf', DMSansRegularB64);
                pdf.addFont('DMSans-Regular.ttf', 'DMSans', 'normal');
                pdf.addFileToVFS('DMSans-Bold.ttf', DMSansBoldB64);
                pdf.addFont('DMSans-Bold.ttf', 'DMSans', 'bold');
                pdf.setFont('DMSans', 'normal');

                console.log("PDF engine initialized with DMSans Unicode support.");

                // Asynchronously load the Front and Back canvas images to verify dimensions
                const loadImg = (src) => {
                    return new Promise((res) => {
                        if (!src) return res(null);
                        const img = new Image();
                        img.onload = () => res(img);
                        img.onerror = () => res(null);
                        img.src = src;
                    });
                };

                const [loadedFront, loadedBack] = await Promise.all([
                    loadImg(designData.imgFront),
                    loadImg(designData.imgBack)
                ]);

                // ── HELPER STYLING FUNCTIONS ──────────────────────────────────
                function hexToRgb(hex) {
                    const r = parseInt(hex.slice(1, 3), 16);
                    const g = parseInt(hex.slice(3, 5), 16);
                    const b = parseInt(hex.slice(5, 7), 16);
                    return { r, g, b };
                }
                function setPdfFillColor(hex) {
                    const rgb = hexToRgb(hex);
                    pdf.setFillColor(rgb.r, rgb.g, rgb.b);
                }
                function setPdfDrawColor(hex) {
                    const rgb = hexToRgb(hex);
                    pdf.setDrawColor(rgb.r, rgb.g, rgb.b);
                }
                function setPdfTextColor(hex) {
                    const rgb = hexToRgb(hex);
                    pdf.setTextColor(rgb.r, rgb.g, rgb.b);
                }

                function drawBlock(title, x, y, w, h) {
                    pdf.setLineWidth(0.3);
                    setPdfDrawColor('#d9e2ec');
                    pdf.setFillColor(255, 255, 255);
                    pdf.roundedRect(x, y, w, h, 2, 2, 'FD');

                    pdf.setFont('DMSans', 'bold');
                    pdf.setFontSize(8.5);
                    setPdfTextColor('#0088c9');
                    pdf.text(title, x + 4, y + 6);

                    // divider line
                    setPdfDrawColor('#e2e8f0');
                    pdf.setLineWidth(0.15);
                    pdf.line(x + 4, y + 8, x + w - 4, y + 8);
                }

                function fitImageInsideBox(imgW, imgH, boxW, boxH) {
                    const imgRatio = imgW / imgH;
                    const boxRatio = boxW / boxH;
                    let w, h, xOffset, yOffset;
                    if (imgRatio > boxRatio) {
                        w = boxW;
                        h = boxW / imgRatio;
                        xOffset = 0;
                        yOffset = (boxH - h) / 2;
                    } else {
                        h = boxH;
                        w = boxH * imgRatio;
                        xOffset = (boxW - w) / 2;
                        yOffset = 0;
                    }
                    return { w, h, x: xOffset, y: yOffset };
                }

                // ── 1. WATERMARK BACKGROUND (Drawn first under content) ───────
                pdf.setFont('DMSans', 'bold');
                pdf.setTextColor(248, 250, 252); // extremely faint gray color matching 0.04 opacity
                pdf.setFontSize(32);
                pdf.text("ĐỒNG PHỤC MRS LINH", 105, 150, { align: 'center', angle: 30 });

                // ── 2. HEADER BLOCK (y: 10 to 32) ─────────────────────────────
                // Brand Left group
                pdf.setFont('DMSans', 'bold');
                pdf.setFontSize(18);
                setPdfTextColor('#0088c9');
                pdf.text("MRS LINH", 10, 16);

                pdf.setFontSize(7.5);
                setPdfTextColor('#0f172a');
                pdf.text("U  N  I  F  O  R  M", 10, 20);

                pdf.setFont('DMSans', 'normal');
                pdf.setFontSize(5.2);
                setPdfTextColor('#64748b');
                pdf.text("ĐỒNG PHỤC CHUYÊN NGHIỆP", 10, 23.2);

                // Vertical Divider Line
                setPdfDrawColor('#cbd5e1');
                pdf.setLineWidth(0.2);
                pdf.line(42, 11, 42, 29);

                // Brand details next to divider
                pdf.setFont('DMSans', 'bold');
                pdf.setFontSize(7.5);
                setPdfTextColor('#0f172a');
                pdf.text("CÔNG TY TNHH DV TM ĐT ĐỒNG PHỤC MRS LINH", 45, 14);

                pdf.setFont('DMSans', 'normal');
                pdf.setFontSize(6.5);
                setPdfTextColor('#475569');
                pdf.text("📍 Địa chỉ: 16/6 Lưu Trọng Lư, Quy Nhơn, Gia Lai", 45, 18);
                pdf.text("📞 SĐT/Zalo: 0934.975.913", 45, 22);
                
                pdf.setFont('DMSans', 'bold');
                setPdfTextColor('#0088c9');
                pdf.text("✉️ mrslinh@inaodongphucmrslinh.com", 45, 26);

                // Document Title Right group
                pdf.setFont('DMSans', 'bold');
                pdf.setFontSize(15);
                setPdfTextColor('#0088c9');
                pdf.text("BẢNG MÔ TẢ SẢN PHẨM", 200, 15, { align: 'right' });

                pdf.setFont('DMSans', 'normal');
                pdf.setFontSize(7);
                setPdfTextColor('#475569');
                pdf.text(`Mã hồ sơ: ML-${designData.recordCode || '810834'} | TRANG 1/1`, 200, 19, { align: 'right' });
                
                pdf.setFontSize(6.5);
                setPdfTextColor('#94a3b8');
                pdf.text("Hệ thống 3D Mrs Linh", 200, 22, { align: 'right' });

                // Top Line Blue Accent
                pdf.setLineWidth(1.0);
                setPdfDrawColor('#0088c9');
                pdf.line(10, 31, 200, 31);

                // ── 3. CUSTOMER DETAILS BAR (y: 36 to 56) ─────────────────────
                pdf.setLineWidth(0.3);
                setPdfDrawColor('#d9e2ec');
                pdf.setFillColor(248, 250, 252); // #f8fafc slate background
                pdf.roundedRect(10, 36, 190, 20, 2, 2, 'FD');

                // Customer contact
                pdf.setFont('DMSans', 'bold');
                pdf.setFontSize(7.5);
                setPdfTextColor('#d60000');
                pdf.text("THÔNG TIN KHÁCH HÀNG", 14, 41);

                pdf.setFontSize(9);
                setPdfTextColor('#0f172a');
                pdf.text(designData.fullname, 14, 46);

                pdf.setFont('DMSans', 'normal');
                pdf.setFontSize(7.5);
                setPdfTextColor('#475569');
                pdf.text(`Số điện thoại / Zalo: ${designData.phone}`, 14, 51);

                // Creator & Status (Right)
                pdf.setFont('DMSans', 'bold');
                pdf.setFontSize(7.5);
                setPdfTextColor('#64748b');
                pdf.text("THỜI GIAN KHỞI TẠO", 196, 41, { align: 'right' });

                pdf.setFont('DMSans', 'normal');
                pdf.setFontSize(8);
                setPdfTextColor('#475569');
                pdf.text(designData.date || new Date().toLocaleDateString('vi-VN'), 196, 46, { align: 'right' });

                pdf.setFont('DMSans', 'bold');
                setPdfTextColor('#0088c9');
                pdf.text("Trạng thái: Đã duyệt phác thảo 3D", 196, 51, { align: 'right' });

                // ── 4. LEFT COLUMN BLOCKS (x: 10, y: 62, width: 78) ────────────
                
                // Block 1: SỐ LƯỢNG ĐẶT HÀNG
                const sizeQuantities = designData.sizeQuantities || [];
                const numRows = Math.max(1, sizeQuantities.length);
                const block1Height = 11 + 5 + (numRows * 5) + 5 + 3; // 24 + 5*numRows

                drawBlock("SỐ LƯỢNG ĐẶT HÀNG", 10, 62, 78, block1Height);

                // Table Header Block
                pdf.setFillColor(15, 23, 42); // dark navy #0f172a
                pdf.rect(14, 72, 70, 5, 'F');

                pdf.setFont('DMSans', 'bold');
                pdf.setFontSize(7);
                pdf.setTextColor(255, 255, 255);
                pdf.text("Form", 16, 75.5);
                pdf.text("Size", 40, 75.5, { align: 'center' });
                pdf.text("Thông Số Chuẩn", 50, 75.5);
                pdf.text("Số Lượng", 82, 75.5, { align: 'right' });

                // Rows listing sizes
                pdf.setLineWidth(0.15);
                setPdfDrawColor('#e2e8f0');

                sizeQuantities.forEach((item, idx) => {
                    const rowY = 77 + (idx * 5);
                    
                    if (idx % 2 === 1) {
                        pdf.setFillColor(248, 250, 252);
                        pdf.rect(14, rowY, 70, 5, 'F');
                    }

                    pdf.line(14, rowY + 5, 84, rowY + 5);

                    // Form label styling
                    const isFemale = item.form.includes('Nữ');
                    setPdfTextColor(isFemale ? '#ec4899' : '#0284c7');
                    pdf.setFont('DMSans', 'bold');
                    pdf.setFontSize(6.5);
                    pdf.text(item.form, 16, rowY + 3.5);

                    setPdfTextColor('#1e293b');
                    pdf.text(item.size, 40, rowY + 3.5, { align: 'center' });

                    setPdfTextColor('#64748b');
                    pdf.setFont('DMSans', 'normal');
                    pdf.setFontSize(6);
                    pdf.text(item.guide, 50, rowY + 3.5);

                    setPdfTextColor('#0284c7');
                    pdf.setFont('DMSans', 'bold');
                    pdf.setFontSize(6.5);
                    pdf.text(`${item.qty} chiếc`, 82, rowY + 3.5, { align: 'right' });
                });

                // Summary Row
                const totalRowY = 77 + (numRows * 5);
                pdf.setFillColor(241, 245, 249);
                pdf.rect(14, totalRowY, 70, 5, 'F');
                pdf.line(14, totalRowY, 84, totalRowY);
                pdf.line(14, totalRowY + 5, 84, totalRowY + 5);

                pdf.setFont('DMSans', 'bold');
                pdf.setFontSize(7);
                setPdfTextColor('#0f172a');
                pdf.text("TỔNG CỘNG SỐ LƯỢNG MẪU", 16, totalRowY + 3.5);

                setPdfTextColor('#d60000');
                pdf.text(`${designData.totalQty} chiếc`, 82, totalRowY + 3.5, { align: 'right' });

                // Block 2: ĐẶC TẢ PHỐI MÀU & CHI TIẾT
                const block2Y = 62 + block1Height + 4;
                const colorSpecs = designData.colorSpecs || [];
                const pocketSpecs = designData.pocketSpecs || [];
                const reflectiveSpecs = designData.reflectiveSpecs || [];
                const hasPockets = pocketSpecs.length > 0;
                const hasReflective = reflectiveSpecs.length > 0;

                const block2Height = 12 + 4 + (colorSpecs.length * 4.5) + (hasPockets ? 5 : 0) + (hasReflective ? 5 : 0) + 4;

                drawBlock("ĐẶC TẢ PHỐI MÀU & CHI TIẾT", 10, block2Y, 78, block2Height);

                pdf.setFont('DMSans', 'bold');
                pdf.setFontSize(7.5);
                setPdfTextColor('#0284c7');
                pdf.text(`Mẫu sản phẩm: ${designData.productName}`, 14, block2Y + 13);

                pdf.setFontSize(6.5);
                pdf.setLineWidth(0.15);
                setPdfDrawColor('#f1f5f9');

                colorSpecs.forEach((item, idx) => {
                    const rowY = block2Y + 17 + (idx * 4.5);
                    pdf.line(14, rowY + 3.5, 84, rowY + 3.5);

                    if (item.colorHex) {
                        pdf.setLineWidth(0.2);
                        setPdfDrawColor('#cbd5e1');
                        const rgb = hexToRgb(item.colorHex);
                        pdf.setFillColor(rgb.r, rgb.g, rgb.b);
                        pdf.roundedRect(14, rowY + 1.0, 2.2, 2.2, 0.4, 0.4, 'FD');
                    }

                    pdf.setFont('DMSans', 'bold');
                    setPdfTextColor('#475569');
                    pdf.text(item.label, 18.5, rowY + 2.8);

                    pdf.setFont('DMSans', 'normal');
                    setPdfTextColor('#0f172a');
                    pdf.text(item.value, 82, rowY + 2.8, { align: 'right' });
                });

                let nextY = block2Y + 17 + (colorSpecs.length * 4.5);
                if (hasPockets) {
                    pdf.setFont('DMSans', 'bold');
                    setPdfTextColor('#475569');
                    pdf.text("📂 Cấu hình túi:", 14, nextY + 3.2);
                    pdf.setFont('DMSans', 'normal');
                    setPdfTextColor('#0f172a');
                    pdf.text(pocketSpecs.join(', '), 32, nextY + 3.2);
                    nextY += 5;
                }

                if (hasReflective) {
                    pdf.setFont('DMSans', 'bold');
                    setPdfTextColor('#475569');
                    pdf.text("⚡ Phản quang:", 14, nextY + 3.2);
                    pdf.setFont('DMSans', 'normal');
                    setPdfTextColor('#0f172a');
                    pdf.text(reflectiveSpecs.join(', '), 32, nextY + 3.2);
                }

                // Block 3: XÁC NHẬN THIẾT KẾ 3D (Bottom left column y: 250 to 278)
                pdf.setLineWidth(0.3);
                setPdfDrawColor('#cbd5e1');
                pdf.setFillColor(248, 250, 252);
                pdf.roundedRect(10, 250, 78, 28, 2, 2, 'FD');

                // Customer Half
                pdf.setFont('DMSans', 'bold');
                pdf.setFontSize(7.5);
                setPdfTextColor('#0f172a');
                pdf.text("ĐẠI DIỆN KHÁCH HÀNG", 29.5, 255.5, { align: 'center' });

                pdf.setFont('DMSans', 'normal');
                pdf.setFontSize(6);
                setPdfTextColor('#64748b');
                pdf.text("(Ký, ghi rõ họ tên & đóng dấu)", 29.5, 258.5, { align: 'center' });

                // Signature placeholder dotted line
                pdf.setLineWidth(0.25);
                setPdfDrawColor('#cbd5e1');
                pdf.setLineDashPattern([0.8, 0.8], 0);
                pdf.line(16, 271, 43, 271);
                pdf.setLineDashPattern([], 0); // Restore solid lines

                // Mrs Linh Half
                pdf.setFont('DMSans', 'bold');
                pdf.setFontSize(7.5);
                setPdfTextColor('#0088c9');
                pdf.text("ĐỒNG PHỤC MRS LINH", 68.5, 255.5, { align: 'center' });

                pdf.setFont('DMSans', 'normal');
                pdf.setFontSize(6);
                setPdfTextColor('#64748b');
                pdf.text("(Hệ thống duyệt tự động qua Zalo)", 68.5, 258.5, { align: 'center' });

                pdf.setFont('DMSans', 'bold');
                pdf.setFontSize(7.5);
                setPdfTextColor('#0088c9');
                pdf.text("ĐÃ XÁC NHẬN THIẾT KẾ 3D", 68.5, 271, { align: 'center' });


                // ── 5. RIGHT COLUMN BLOCKS (x: 94, y: 62, width: 106) ───────────
                
                // Block 1: Front View Card
                pdf.setLineWidth(0.3);
                setPdfDrawColor('#d9e2ec');
                pdf.setFillColor(255, 255, 255);
                pdf.roundedRect(94, 62, 106, 76, 2, 2, 'FD');

                if (loadedFront) {
                    const fitFront = fitImageInsideBox(loadedFront.width, loadedFront.height, 98, 56);
                    pdf.addImage(loadedFront, 'PNG', 94 + 4 + fitFront.x, 62 + 3 + fitFront.y, fitFront.w, fitFront.h);
                }

                // Label Badge Pill Front
                pdf.setFillColor(224, 242, 254);
                pdf.roundedRect(127, 131, 40, 5, 1, 1, 'F');
                pdf.setFont('DMSans', 'bold');
                pdf.setFontSize(6.5);
                setPdfTextColor('#0284c7');
                pdf.text("MẶT TRƯỚC (FRONT VIEW)", 147, 134.5, { align: 'center' });

                // Block 2: Back View Card
                pdf.setFillColor(255, 255, 255);
                pdf.roundedRect(94, 142, 106, 76, 2, 2, 'FD');

                if (loadedBack) {
                    const fitBack = fitImageInsideBox(loadedBack.width, loadedBack.height, 98, 56);
                    pdf.addImage(loadedBack, 'PNG', 94 + 4 + fitBack.x, 142 + 3 + fitBack.y, fitBack.w, fitBack.h);
                }

                // Label Badge Pill Back
                pdf.setFillColor(224, 242, 254);
                pdf.roundedRect(127, 211, 40, 5, 1, 1, 'F');
                pdf.setFont('DMSans', 'bold');
                pdf.setFontSize(6.5);
                setPdfTextColor('#0284c7');
                pdf.text("MẶT SAU (BACK VIEW)", 147, 214.5, { align: 'center' });

                // Block 3: Logo / Pattern characteristics spec board (y: 222 to 278)
                drawBlock("ĐẶC TÍNH LOGO / HỌA TIẾT", 94, 222, 106, 56);

                const logos = designData.logos || [];
                const patterns = designData.patterns || [];

                if (logos.length === 0 && patterns.length === 0) {
                    pdf.setFont('DMSans', 'italic');
                    pdf.setFontSize(7.5);
                    setPdfTextColor('#64748b');
                    pdf.text("Đặc tính logo / họa tiết: chưa gắn vào thiết kế", 98, 237);
                } else {
                    pdf.setFontSize(6.5);
                    pdf.setLineWidth(0.15);
                    setPdfDrawColor('#cbd5e1');

                    const itemsToDraw = [];
                    logos.forEach((logo, idx) => {
                        itemsToDraw.push({
                            type: 'logo',
                            title: logo.isFree ? `Logo Tự Do #${idx + 1}: ${logo.position}` : `Logo Cố Định: ${logo.position}`,
                            subtext: `Scale: ${logo.scale}${logo.isFree ? 'px' : '%'} | Công nghệ: ${logo.printStyle === 'theu' ? 'Thêu vi tính satin' : 'In PET sắc nét'}`,
                            imgElement: logo.imgElement
                        });
                    });
                    patterns.forEach((pattern, idx) => {
                        itemsToDraw.push({
                            type: 'pattern',
                            title: `Họa Tiết Toàn Thân: ${pattern.angle}`,
                            subtext: `Scale: ${pattern.scale}% | Opacity: ${pattern.opacity}% | Kiểu in: ${pattern.printType === 'chuyen-nhiet' ? 'In chuyển nhiệt' : 'In kỹ thuật số'}`,
                            imgElement: pattern.imgElement
                        });
                    });

                    const visibleItems = itemsToDraw.slice(0, 4);
                    visibleItems.forEach((item, idx) => {
                        const rowY = 232 + (idx * 11);

                        // Thumbnail Box
                        pdf.setFillColor(255, 255, 255);
                        pdf.setLineWidth(0.15);
                        setPdfDrawColor('#d9e2ec');
                        pdf.roundedRect(98, rowY, 9, 9, 1, 1, 'FD');

                        if (item.imgElement) {
                            const imgW = item.imgElement.naturalWidth || 100;
                            const imgH = item.imgElement.naturalHeight || 100;
                            const fitThumb = fitImageInsideBox(imgW, imgH, 8, 8);
                            pdf.addImage(item.imgElement, 'PNG', 98 + 0.5 + fitThumb.x, rowY + 0.5 + fitThumb.y, fitThumb.w, fitThumb.h);
                        }

                        // Item details text
                        pdf.setFont('DMSans', 'bold');
                        setPdfTextColor('#0f172a');
                        pdf.text(item.title, 109, rowY + 3.5);

                        pdf.setFont('DMSans', 'normal');
                        setPdfTextColor('#64748b');
                        pdf.text(item.subtext, 109, rowY + 7.2);
                    });
                }


                // ── 6. FOOTER BLOCK (y: 282 to 290) ───────────────────────────
                pdf.setLineWidth(0.15);
                setPdfDrawColor('#cbd5e1');
                pdf.setLineDashPattern([1, 1], 0);
                pdf.line(10, 281.5, 200, 281.5);
                pdf.setLineDashPattern([], 0); // Restore solid lines

                pdf.setFont('DMSans', 'normal');
                pdf.setFontSize(7.5);
                setPdfTextColor('#64748b');
                pdf.text("Thiết kế & Sản xuất bởi Mrs Linh Uniform | Hotline: 0934.975.913", 10, 286.5);

                pdf.text("www.inaodongphucmrslinh.com", 105, 286.5, { align: 'center' });

                // Page Number Pill indicator
                pdf.setFillColor(224, 242, 254);
                pdf.roundedRect(188, 283.5, 12, 4, 1.2, 1.2, 'F');
                pdf.setFont('DMSans', 'bold');
                pdf.setFontSize(6.2);
                setPdfTextColor('#0284c7');
                pdf.text("Trang 1/1", 194, 286.5, { align: 'center' });

                // Delete any empty trailing pages that might have been automatically created by jsPDF layout engine
                const pageCount = pdf.internal.getNumberOfPages();
                if (pageCount > 1) {
                    for (let p = pageCount; p > 1; p--) {
                        pdf.deletePage(p);
                    }
                }

                pdf.save(`MRS_LINH_DESIGN_${designData.product.toUpperCase()}_${designData.phone}.pdf`);
                resolve();
            } catch (err) {
                reject(err);
            }
        });
    };
})();
